// The agent's keys (Agent-Protocol.md sections 3 and 5). PROTOTYPE. Agent-only: a host page must never import this.
//
// A NEW identity is generated here (first cut: fresh material only, never an imported or rebuilt older seed):
//   - a random identity seed -> the .me identity (identityHash, its own key), used to sign the registration statement;
//   - a random Ed25519 AGENT key, generated by WebCrypto as non-extractable and kept in this origin's IndexedDB.
// The identity is stored PENDING -- with its seed -- BEFORE the registration is sent, and the seed is deleted once the
// resource confirms the registration (201, or 200 for a retry of the same one). So an answer lost in transit, or a
// save the server could not confirm, never leaves a namespace registered whose key this agent no longer holds: the
// agent retries the same registration (same identity, same key, fresh proofs) until it is confirmed. After that the
// identity never has a seed anywhere, and every proof is signed with the agent key. Nothing here leaves the agent
// except public keys and signatures.
//
// Not in this cut (stated): an unlock secret over the stored key or the pending seed (they are protected by the origin
// and the device only), lock, recovery, rotation, several devices.
import MeKernel from 'this.me';
import { PROOF_V2, base64urlBytes, buildV2Bytes, newRequestId, type V2Fields, type V2RegisterFields } from './protocol';

const DB = 'me-agent';
const STORE = 'identities';

export type AgentIdentity = {
  identityHash: string;
  /** The ROOT the identity was created under (e.g. `cleaker.me`): what requests name, and what identities are listed by. */
  namespace: string;
  /** The namespace the identity claimed under that root (`<handle>.<root>`), as the server confirmed at registration. */
  claimedNamespace?: string;
  keyId: string;
  /** Agent public key, JWK `x` (base64url). */
  agentKey: string;
  privateKey: CryptoKey;
  createdAt: number;
  /** `pending` until the resource confirmed the registration; only `registered` identities can approve anything. */
  status?: 'pending' | 'registered' | 'local-test';
  /** The resource (origin) the identity registers with. */
  resource?: string;
  /** The `@` handle the identity proves under. */
  handle?: string;
  /** PENDING ONLY: the identity seed (hex), kept to retry the registration; deleted once it is confirmed. */
  pendingSeed?: string;
};

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB, 1);
    req.onupgradeneeded = () => req.result.createObjectStore(STORE, { keyPath: 'identityHash' });
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function put(identity: AgentIdentity): Promise<void> {
  const db = await openDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).put(identity);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
  db.close();
}

export async function listIdentities(namespace?: string): Promise<AgentIdentity[]> {
  const db = await openDb();
  const all = await new Promise<AgentIdentity[]>((resolve, reject) => {
    const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    req.onsuccess = () => resolve(req.result as AgentIdentity[]);
    req.onerror = () => reject(req.error);
  });
  db.close();
  // Only confirmed identities can approve anything. A pending one still holds a seed; a local-test
  // identity was never registered with a resource and must not be offered to approve a request.
  return all.filter((i) => (i.status === 'registered' || !i.status) && (!namespace || i.namespace === namespace));
}

function isHomeIdentity(i: AgentIdentity): boolean {
  return i.status === 'registered' || i.status === 'local-test' || !i.status;
}

/** Identities the keys home can show: confirmed ones, plus a disposable local test .me. Never pending. */
export async function listHomeIdentities(): Promise<AgentIdentity[]> {
  const db = await openDb();
  const all = await new Promise<AgentIdentity[]>((resolve, reject) => {
    const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    req.onsuccess = () => resolve(req.result as AgentIdentity[]);
    req.onerror = () => reject(req.error);
  });
  db.close();
  return all.filter(isHomeIdentity);
}

/**
 * A disposable test identity for this origin only: generated in the browser, never sent
 * anywhere, never registered with a resource. The seed is used once to derive the
 * identity hash and is not stored. Existing local-test identities are reused so this
 * never overwrites or multiplies them.
 */
export async function newLocalTestIdentity(): Promise<AgentIdentity> {
  const existing = (await listHomeIdentities()).find((i) => i.status === 'local-test');
  if (existing) return existing;
  const seedBytes = new Uint8Array(32);
  crypto.getRandomValues(seedBytes);
  let seed = Array.from(seedBytes, (b) => b.toString(16).padStart(2, '0')).join('');
  seedBytes.fill(0);
  const handle = 'test';
  const root = 'local';
  const pair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair;
  const agentKey = String(((await crypto.subtle.exportKey('jwk', pair.publicKey)) as JsonWebKey).x || '');
  const keyId = await keyIdOf(agentKey);
  const { identityHash, claimedNamespace } = await proveWith(seed, handle, root, '{}');
  seed = '';
  const identity: AgentIdentity = {
    identityHash,
    namespace: root,
    claimedNamespace,
    keyId,
    agentKey,
    privateKey: pair.privateKey,
    createdAt: Date.now(),
    status: 'local-test',
    handle,
  };
  await put(identity);
  return identity;
}

/** The registration this agent has not finished with `resource` under `namespace`, if any (the most recent). */
export async function pendingRegistration(resource: string, namespace: string): Promise<AgentIdentity | null> {
  const db = await openDb();
  const all = await new Promise<AgentIdentity[]>((resolve, reject) => {
    const req = db.transaction(STORE, 'readonly').objectStore(STORE).getAll();
    req.onsuccess = () => resolve(req.result as AgentIdentity[]);
    req.onerror = () => reject(req.error);
  });
  db.close();
  const pending = all.filter((i) => i.status === 'pending' && i.resource === resource && i.namespace === namespace && i.pendingSeed);
  return pending.sort((a, b) => b.createdAt - a.createdAt)[0] ?? null;
}

async function remove(identityHash: string): Promise<void> {
  const db = await openDb();
  await new Promise<void>((resolve, reject) => {
    const tx = db.transaction(STORE, 'readwrite');
    tx.objectStore(STORE).delete(identityHash);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
  db.close();
}

async function keyIdOf(agentKey: string): Promise<string> {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`me-agent-key:${agentKey}`)));
  return Array.from(digest.slice(0, 16), (b) => b.toString(16).padStart(2, '0')).join('');
}

export async function signV2(identity: AgentIdentity, fields: V2Fields): Promise<{ bytes: string; signature: string }> {
  const bytes = buildV2Bytes(fields);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'Ed25519' }, identity.privateKey, new TextEncoder().encode(bytes)));
  return { bytes, signature: base64urlBytes(sig) };
}

export type RegistrationBody = {
  /** The v2 registration statement, signed by the agent key. */
  statement: { bytes: string; signature: string };
  /** The new identity's own (v1-format) proof over the same statement: it binds the identityHash to the agent key. */
  identityProof: { identityHash: string; publicKey: string; message: string; signature: string };
};

/**
 * Generates a new identity and its agent key and STORES IT PENDING (with its seed) before anything is sent: whatever
 * happens to the registration request, the agent still holds what it needs to finish it.
 */
export async function newPendingIdentity(input: { namespace: string; resource: string; handle?: string }): Promise<AgentIdentity> {
  const seedBytes = new Uint8Array(32);
  crypto.getRandomValues(seedBytes);
  const seed = Array.from(seedBytes, (b) => b.toString(16).padStart(2, '0')).join('');
  seedBytes.fill(0);
  // The identity's name (its `@` expression): prove() needs one. Given, or random for a test identity.
  const handle = input.handle && /^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(input.handle) ? input.handle : `id${newRequestId().slice(0, 10)}`;
  const pair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify'])) as CryptoKeyPair;
  const agentKey = String(((await crypto.subtle.exportKey('jwk', pair.publicKey)) as JsonWebKey).x || '');
  const keyId = await keyIdOf(agentKey);
  const { identityHash, claimedNamespace } = await proveWith(seed, handle, input.namespace, '{}');
  const identity: AgentIdentity = {
    identityHash, namespace: input.namespace, claimedNamespace, keyId, agentKey, privateKey: pair.privateKey,
    createdAt: Date.now(), status: 'pending', resource: input.resource, handle, pendingSeed: seed,
  };
  await put(identity);
  return identity;
}

/** A .me proof from the pending seed (the identity's own key), over `challenge`. */
async function proveWith(seed: string, handle: string, root: string, challenge: string) {
  const me = new (MeKernel as any)(seed);
  me['@'](handle);
  const proof = await me['!'].prove({ rootNamespace: root, challenge });
  const identityHash = String(proof.identityHash || '');
  if (!identityHash) throw new Error('IDENTITY_UNAVAILABLE');
  // The namespace the identity proof names (prove(): `<handle>.<root>`); the server must confirm exactly this one.
  let claimedNamespace = `${handle}.${root}`;
  try { claimedNamespace = String(JSON.parse(String(proof.message)).namespace || claimedNamespace); } catch { /* the default above */ }
  return { identityHash, claimedNamespace, proof };
}

/**
 * The registration to send for a PENDING identity: a fresh statement (new nonce and time) signed by its agent key, and
 * a fresh identity proof over it. The same call serves the first attempt and every retry of the same registration.
 */
export async function registrationFor(identity: AgentIdentity, input: { origin: string; ttlMs?: number }): Promise<RegistrationBody> {
  if (identity.status !== 'pending' || !identity.pendingSeed || !identity.handle || !identity.resource) throw new Error('NOT_PENDING');
  const issuedAt = Date.now();
  const fields: V2RegisterFields = {
    v: PROOF_V2, op: 'register', identityHash: identity.identityHash, namespace: identity.namespace, keyId: identity.keyId, agentKey: identity.agentKey,
    nonce: newRequestId(), issuedAt, expiresAt: issuedAt + (input.ttlMs ?? 60_000), origin: input.origin, audience: identity.resource,
  };
  const statement = await signV2(identity, fields);
  const { proof } = await proveWith(identity.pendingSeed, identity.handle, identity.namespace, statement.bytes);
  return {
    statement,
    identityProof: { identityHash: String(proof.identityHash), publicKey: String(proof.publicKey), message: String(proof.message), signature: String(proof.signature) },
  };
}

/** The resource confirmed the registration: keep the identity, drop its seed for good. */
export async function confirmRegistered(identity: AgentIdentity): Promise<AgentIdentity> {
  const { pendingSeed: _dropped, ...rest } = identity;
  const registered: AgentIdentity = { ...rest, status: 'registered' };
  await put(registered);
  return registered;
}

/** The resource refused this registration for good (a name or identity conflict): forget the pending identity. */
export async function abandonPending(identity: AgentIdentity): Promise<void> {
  if (identity.status === 'pending') await remove(identity.identityHash);
}

export const storeIdentity = put;

/** The path a resource server takes registrations at (the monad's route; the test verifier serves the same one). */
export const AGENT_REGISTER_PATH = '/api/v1/agent/register';
